import{_ as Q,C as a,o as n,c as e,a6 as s,j as r,a as o,E as m,w as l}from"./chunks/framework.BrkgobfX.js";const f=JSON.parse('{"title":"归一化 · RMSNorm、Pre / Post / 三明治、QK-Norm","description":"一个“把归一化放哪儿”的小选择，如何实实在在左右训练稳定性。RMSNorm 早已统一；真正还在分歧的是放置：多数 Pre-Norm，OLMo 2 偏要回到 Post-Norm，Gemma 用前后都放的三明治，而 QK-Norm 与注意力输出门控正在成为新标配。","frontmatter":{"title":"归一化 · RMSNorm、Pre / Post / 三明治、QK-Norm","description":"一个“把归一化放哪儿”的小选择，如何实实在在左右训练稳定性。RMSNorm 早已统一；真正还在分歧的是放置：多数 Pre-Norm，OLMo 2 偏要回到 Post-Norm，Gemma 用前后都放的三明治，而 QK-Norm 与注意力输出门控正在成为新标配。","source":"https://daiw.org/manual/llm-anatomy/normalization"},"headers":[],"relativePath":"manual/llm/llm-anatomy/normalization.md","filePath":"manual/llm/llm-anatomy/normalization.md"}'),g={name:"manual/llm/llm-anatomy/normalization.md"},p={style:{overflow:"visible","min-height":"1px","min-width":"1px","vertical-align":"-0.439ex"},xmlns:"http://www.w3.org/2000/svg",width:"5.351ex",height:"2.329ex",role:"img",focusable:"false",viewBox:"0 -835.3 2365.1 1029.3","aria-hidden":"true"};function T(N,t,u,P,h,x){const i=a("mjx-assistive-mml"),d=a("mjx-container");return n(),e("div",null,[t[13]||(t[13]=s('<h1 id="归一化-·-rmsnorm、pre-post-三明治、qk-norm" tabindex="-1">归一化 · RMSNorm、Pre / Post / 三明治、QK-Norm <a class="header-anchor" href="#归一化-·-rmsnorm、pre-post-三明治、qk-norm" aria-label="Permalink to &quot;归一化 · RMSNorm、Pre / Post / 三明治、QK-Norm&quot;">​</a></h1><blockquote><p>一个“把归一化放哪儿”的小选择，如何实实在在左右训练稳定性。RMSNorm 早已统一；真正还在分歧的是放置：多数 Pre-Norm，OLMo 2 偏要回到 Post-Norm，Gemma 用前后都放的三明治，而 QK-Norm 与注意力输出门控正在成为新标配。</p></blockquote><p>归一化（Normalization）是个容易被当作“例行公事”的零件——不就是把数值缩一缩、稳住训练嘛。但恰恰在“<strong>放哪儿</strong>”这个细节上，各家藏着不同心思，而且直接关系到<strong>几百层的大模型能不能训得稳、不崩</strong>。</p><h2 id="先说已经统一的-rmsnorm" tabindex="-1">先说已经统一的：RMSNorm <a class="header-anchor" href="#先说已经统一的-rmsnorm" aria-label="Permalink to &quot;先说已经统一的：RMSNorm&quot;">​</a></h2><p>nanoGPT 里用的是 <strong>LayerNorm</strong>：先减均值、再除标准差，把每个向量拉回“零均值、单位方差”。</p><p>现代模型几乎全换成了 <strong>RMSNorm</strong>（Zhang &amp; Sennrich，2019）：<strong>省掉“减均值”那一步，只除以均方根（RMS）</strong>。少算一个统计量，更快；实践证明<strong>效果不掉</strong>。所以和 RoPE、SwiGLU 一样，RMSNorm 是“2024 出厂设置”，不是谁的创新。</p><p>真正还有分歧、值得对比的，是下面这个——<strong>归一化到底放在子层的前面、后面，还是前后都放。</strong></p><h2 id="分歧点-norm-放前-pre-还是放后-post" tabindex="-1">分歧点：Norm 放前（Pre）还是放后（Post） <a class="header-anchor" href="#分歧点-norm-放前-pre-还是放后-post" aria-label="Permalink to &quot;分歧点：Norm 放前（Pre）还是放后（Post）&quot;">​</a></h2><p>回忆一个 Transformer 子层的三件套：<strong>归一化、子层运算（注意力 / 前馈）、残差相加</strong>。这三者的<strong>顺序</strong>，有讲究：</p><ul><li><strong>Post-Norm（原始 Transformer，2017）</strong>：先算子层、和残差相加，<strong>最后</strong>再归一化。<code>x = Norm(x + Sublayer(x))</code>。这是 Vaswani 那篇原版的做法。它的毛病是<strong>深了难训</strong>——梯度容易爆或消，当年得靠学习率 warmup 小心伺候。</li><li><strong>Pre-Norm（GPT-2 起的标配）</strong>：<strong>先</strong>归一化，再进子层，输出直接加回残差。<code>x = x + Sublayer(Norm(x))</code>。你在 <a href="https://daiw.org/manual/nanogpt/model-overview" target="_blank" rel="noreferrer">nanoGPT 的 Block</a> 里读到的正是它。好处是<strong>残差是一条干净的“高速公路”</strong>，梯度直通到底，深网络也稳，不太需要小心翼翼。</li></ul><p><strong>Pre-Norm 赢麻了，成了默认。</strong> 但它并非完美：Pre-Norm 下，<strong>残差流的数值会随深度越滚越大</strong>，极深的模型这也会带来隐患。于是，在“Pre 已成共识”的大背景下，偏偏有人回头去动这个开关——</p><h2 id="两个-不随大流-的-olmo-2-与-gemma" tabindex="-1">两个“不随大流”的：OLMo 2 与 Gemma <a class="header-anchor" href="#两个-不随大流-的-olmo-2-与-gemma" aria-label="Permalink to &quot;两个“不随大流”的：OLMo 2 与 Gemma&quot;">​</a></h2><p><strong>OLMo 2（Ai2，2024）偏要用回 Post-Norm。</strong> 但它做了改良：归一化放在子层<strong>之后</strong>、却仍在<strong>残差内部</strong>（论文称之为“reordered norm”）。团队发现：<strong>Post-Norm 配合 QK-Norm（下面讲），能显著改善训练时梯度范数的增长曲线和尖峰</strong>，让训练更稳。这是个基于实测、逆共识的选择——很能说明“Pre-Norm 是默认，但不是铁律”。</p><p><strong>Gemma 2 / 3 则是“我全都要”——三明治归一化（sandwich）</strong>：在每个子层的<strong>前面和后面各放一个 RMSNorm</strong>。等于 Pre 和 Post 的稳定性一起吃，代价是多算一遍归一化。这是 Google DeepMind 求稳的“双保险”。</p><h2 id="新标配-qk-norm-与注意力输出门控" tabindex="-1">新标配：QK-Norm 与注意力输出门控 <a class="header-anchor" href="#新标配-qk-norm-与注意力输出门控" aria-label="Permalink to &quot;新标配：QK-Norm 与注意力输出门控&quot;">​</a></h2><p>除了“放哪儿”，近两年还冒出两个越来越流行的加法：<strong>QK-Norm</strong> 与<strong>注意力输出门控（Gated Attention）</strong>。</p>',16)),r("p",null,[t[2]||(t[2]=r("strong",null,"QK-Norm",-1)),t[3]||(t[3]=o(" 的做法是：在算注意力之前，",-1)),t[4]||(t[4]=r("strong",null,"额外对 Query 和 Key 各做一次归一化",-1)),t[5]||(t[5]=o("（通常在 RoPE 之前）。动机是",-1)),t[6]||(t[6]=r("strong",null,"稳住注意力的打分",-1)),t[7]||(t[7]=o("——回忆 ",-1)),t[8]||(t[8]=r("a",{href:"https://daiw.org/manual/nanogpt/attention",target:"_blank",rel:"noreferrer"},"nanoGPT 注意力",-1)),t[9]||(t[9]=o("里那个 ",-1)),m(d,{class:"MathJax",jax:"SVG",style:{direction:"ltr",position:"relative"}},{default:l(()=>[(n(),e("svg",p,[...t[0]||(t[0]=[r("g",{stroke:"currentColor",fill:"currentColor","stroke-width":"0",transform:"scale(1,-1)"},[r("g",{"data-mml-node":"math"},[r("g",{"data-mml-node":"mi"},[r("path",{"data-c":"1D444",d:"M399 -80Q399 -47 400 -30T402 -11V-7L387 -11Q341 -22 303 -22Q208 -22 138 35T51 201Q50 209 50 244Q50 346 98 438T227 601Q351 704 476 704Q514 704 524 703Q621 689 680 617T740 435Q740 255 592 107Q529 47 461 16L444 8V3Q444 2 449 -24T470 -66T516 -82Q551 -82 583 -60T625 -3Q631 11 638 11Q647 11 649 2Q649 -6 639 -34T611 -100T557 -165T481 -194Q399 -194 399 -87V-80ZM636 468Q636 523 621 564T580 625T530 655T477 665Q429 665 379 640Q277 591 215 464T153 216Q153 110 207 59Q231 38 236 38V46Q236 86 269 120T347 155Q372 155 390 144T417 114T429 82T435 55L448 64Q512 108 557 185T619 334T636 468ZM314 18Q362 18 404 39L403 49Q399 104 366 115Q354 117 347 117Q344 117 341 117T337 118Q317 118 296 98T274 52Q274 18 314 18Z",style:{"stroke-width":"3"}})]),r("g",{"data-mml-node":"msup",transform:"translate(791,0)"},[r("g",{"data-mml-node":"mi"},[r("path",{"data-c":"1D43E",d:"M285 628Q285 635 228 637Q205 637 198 638T191 647Q191 649 193 661Q199 681 203 682Q205 683 214 683H219Q260 681 355 681Q389 681 418 681T463 682T483 682Q500 682 500 674Q500 669 497 660Q496 658 496 654T495 648T493 644T490 641T486 639T479 638T470 637T456 637Q416 636 405 634T387 623L306 305Q307 305 490 449T678 597Q692 611 692 620Q692 635 667 637Q651 637 651 648Q651 650 654 662T659 677Q662 682 676 682Q680 682 711 681T791 680Q814 680 839 681T869 682Q889 682 889 672Q889 650 881 642Q878 637 862 637Q787 632 726 586Q710 576 656 534T556 455L509 418L518 396Q527 374 546 329T581 244Q656 67 661 61Q663 59 666 57Q680 47 717 46H738Q744 38 744 37T741 19Q737 6 731 0H720Q680 3 625 3Q503 3 488 0H478Q472 6 472 9T474 27Q478 40 480 43T491 46H494Q544 46 544 71Q544 75 517 141T485 216L427 354L359 301L291 248L268 155Q245 63 245 58Q245 51 253 49T303 46H334Q340 37 340 35Q340 19 333 5Q328 0 317 0Q314 0 280 1T180 2Q118 2 85 2T49 1Q31 1 31 11Q31 13 34 25Q38 41 42 43T65 46Q92 46 125 49Q139 52 144 61Q147 65 216 339T285 628Z",style:{"stroke-width":"3"}})]),r("g",{"data-mml-node":"mi",transform:"translate(974,363) scale(0.707)"},[r("path",{"data-c":"22A4",d:"M55 642T55 648T59 659T66 666T71 668H708Q723 660 723 648T708 628H409V15Q402 2 391 0Q387 0 384 1T379 3T375 6T373 9T371 13T369 16V628H71Q70 628 67 630T59 637Z",style:{"stroke-width":"3"}})])])])],-1)])])),m(i,{unselectable:"on",display:"inline",style:{top:"0px",left:"0px",clip:"rect(1px, 1px, 1px, 1px)","-webkit-touch-callout":"none","-webkit-user-select":"none","-khtml-user-select":"none","-moz-user-select":"none","-ms-user-select":"none","user-select":"none",position:"absolute",padding:"1px 0px 0px 0px",border:"0px",display:"block",width:"auto",overflow:"hidden"}},{default:l(()=>[...t[1]||(t[1]=[r("math",{xmlns:"http://www.w3.org/1998/Math/MathML"},[r("mi",null,"Q"),r("msup",null,[r("mi",null,"K"),r("mi",{mathvariant:"normal"},"⊤")])],-1)])]),_:1})]),_:1}),t[10]||(t[10]=o("，如果 Q、K 的数值失控，点积会爆、softmax 会走极端、训练会抖。先把 Q、K 归一化，注意力打分就温顺得多，大规模训练更稳。QK-Norm 最早在视觉 Transformer（如 ViT-22B）上被验证有效，如今 ",-1)),t[11]||(t[11]=r("strong",null,"Qwen3、OLMo 2、Gemma、GLM-4.5、GPT-OSS 都用上了",-1)),t[12]||(t[12]=o("，俨然成了新的“出厂设置”。",-1))]),t[14]||(t[14]=s('<p>到了 2026 年的万亿级模型（<a href="https://daiw.org/manual/qwen3-8-max/architecture" target="_blank" rel="noreferrer">Qwen3.8-Max</a> 与 <a href="https://daiw.org/manual/kimi-k3/hybrid-stack" target="_blank" rel="noreferrer">Kimi K3 / K3.1 Pro</a>），又多了一个护栏：<strong>注意力输出门控（Gated Attention / Gated MLA）</strong>——在注意力输出投影回残差流之前，乘上一个由输入算出的 Sigmoid 门控。它既给注意力子层加了非线性表达力，又给每個注意力头装了一个“静音开关”，能把不需要匹配的头直接关掉，从根上消除了注意力汇聚点（attention sink）和长序列激活值爆炸，让超大规模 FP4/FP8 训练更稳。</p><h2 id="一张表看放置之争" tabindex="-1">一张表看放置之争 <a class="header-anchor" href="#一张表看放置之争" aria-label="Permalink to &quot;一张表看放置之争&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模型</th><th>归一化</th><th>放置</th><th>QK-Norm / 输出门控</th></tr></thead><tbody><tr><td>原始 Transformer</td><td>LayerNorm</td><td>Post</td><td>无</td></tr><tr><td>GPT-2 / nanoGPT</td><td>LayerNorm</td><td>Pre</td><td>无</td></tr><tr><td>Llama / Qwen（主流）</td><td>RMSNorm</td><td>Pre</td><td>Qwen3 起有 QK-Norm</td></tr><tr><td><strong>OLMo 2</strong></td><td>RMSNorm</td><td><strong>Post（改良）</strong></td><td><strong>有 QK-Norm</strong></td></tr><tr><td><strong>Gemma 2 / 3</strong></td><td>RMSNorm</td><td><strong>Pre + Post（三明治）</strong></td><td>有 QK-Norm</td></tr><tr><td>GLM-4.5 / GPT-OSS</td><td>RMSNorm</td><td>Pre</td><td>有 QK-Norm</td></tr><tr><td><strong>Qwen3.8-Max / Kimi K3</strong></td><td>RMSNorm（Kimi K3 配合 AttnRes）</td><td>Pre</td><td><strong>有 QK-Norm + 注意力输出 Sigmoid 门控</strong></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>这一章的启示很“工程”：<strong>归一化不改变模型“能表达什么”，只影响“能不能稳稳地训出来”。</strong> 它是那种“选对了没人夸、选错了训到一半崩”的零件。也正因为如此，当一个团队敢逆着“Pre-Norm”的共识去用 Post（OLMo 2）或三明治（Gemma），或者在 90 多层的万亿模型里加上注意力输出门控和跨层注意力残差（Kimi K3），背后都是<strong>扎实的稳定性实测</strong>在撑腰——这类选择，比随大流更值得你留意。</p></div><h2 id="下一维-位置编码怎么撑起几十万上下文" tabindex="-1">下一维：位置编码怎么撑起几十万上下文 <a class="header-anchor" href="#下一维-位置编码怎么撑起几十万上下文" aria-label="Permalink to &quot;下一维：位置编码怎么撑起几十万上下文&quot;">​</a></h2><p>归一化管“训得稳”，下一个维度管“看得远”。RoPE 早已一统位置编码，但把上下文从 4K 拉到 128K、乃至上百万，RoPE 得动点手脚（YaRN 等）；甚至有人提出**干脆不要位置编码（NoPE）**也能外推。这是下一章。👉 <a href="/Front2Full/manual/llm/llm-anatomy/positional-encoding">位置编码与长上下文：RoPE、YaRN，与 NoPE 的挑衅</a></p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li>[1] Vaswani et al. “Attention Is All You Need.” NeurIPS 2017. arXiv:1706.03762. —— 原始 Post-Norm。</li><li>[2] Zhang &amp; Sennrich. “Root Mean Square Layer Normalization.” NeurIPS 2019. arXiv:1910.07467. —— RMSNorm。</li><li>[3] Xiong et al. “On Layer Normalization in the Transformer Architecture.” ICML 2020. arXiv:2002.04745. —— Pre-Norm 的稳定性分析。</li><li>[4] OLMo Team, Ai2. “2 OLMo 2 Furious.” 2024. arXiv:2501.00656. —— 改良 Post-Norm + QK-Norm 的稳定性论证。</li><li>[5] Dehghani et al. “Scaling Vision Transformers to 22 Billion Parameters.” 2023. arXiv:2302.05442. —— QK-Norm 在超大模型上的应用。</li><li>[6] Henry et al. “Query-Key Normalization for Transformers.” EMNLP Findings 2020. arXiv:2010.04245. —— QK-Norm 的早期提出。</li></ul>',8))])}const S=Q(g,[["render",T]]);export{f as __pageData,S as default};
